<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import * as echarts from 'echarts'

type Plan = { name: string; year: number; water: string; impact: string }
const plans: Record<string, Plan[]> = {
  ENGATIVA: [{ name: 'El Porvenir', year: 2016, water: 'Río Bogotá y humedal Jaboque', impact: 'Desarrollo · modificación' }],
  BOSA: [{ name: 'Edén–El Descanso', year: 2023, water: 'Río Tunjuelo', impact: 'Desarrollo · modificación' }, { name: 'La Palestina', year: 2017, water: 'Río Tunjuelo', impact: 'Desarrollo · modificación' }, { name: 'La Marlene', year: 2021, water: 'Río Tunjuelo', impact: 'Desarrollo' }, { name: 'Bosa 37', year: 2021, water: 'Canal Tintal IV y río Bogotá', impact: 'Desarrollo' }],
  FONTIBON: [{ name: 'La Felicidad', year: 2020, water: 'Canal San Francisco y antiguo cauce', impact: 'Desarrollo · modificación' }, { name: 'Procables', year: 2017, water: 'Río Fucha', impact: 'Desarrollo · modificación' }, { name: 'El Chanco', year: 2018, water: 'Humedal Meandro del Say', impact: 'Desarrollo' }],
  KENNEDY: [{ name: 'La Pampa', year: 2023, water: 'Humedal de Techo', impact: 'Desarrollo · modificación' }, { name: 'Tintalito Mazuera Alsacia Oriental', year: 2018, water: 'Canal Fucha y canal Alsacia', impact: 'Desarrollo' }, { name: 'Tintalito Mazuera Occidental', year: 2018, water: 'Canales Alsacia y Magdalena', impact: 'Desarrollo' }],
  USAQUEN: [{ name: 'Contador Oriental', year: 2015, water: 'Quebradas Contador y Medina', impact: 'Desarrollo' }, { name: 'Ciudad La Salle', year: 2021, water: 'Canales El Redil y San Antonio', impact: 'Desarrollo · modificación' }, { name: 'No. 15 Mazda Mavaia (LT)', year: 2020, water: 'Quebradas San Juan y Patiño; humedal Torca', impact: 'Desarrollo' }, { name: 'No. 17 Lucerna (LT)', year: 2021, water: 'Quebrada San Juan y humedal Torca', impact: 'Desarrollo' }, { name: 'No. 10 El Rosario (LT)', year: 2023, water: 'Canal Torca y quebrada Tibabita', impact: 'Desarrollo' }],
  'SAN CRISTOBAL': [{ name: 'La Arboleda', year: 2018, water: 'Quebradas La Chiguaza y Chorro Silverio', impact: 'Desarrollo' }],
  'BARRIOS UNIDOS': [{ name: 'Cafam Floresta', year: 2019, water: 'Canal Rionegro', impact: 'Renovación urbana' }],
  SUBA: [{ name: 'No. 26 El Bosque (LT)', year: 2019, water: 'Humedal Guaymaral', impact: 'Desarrollo' }, { name: 'No. 2 El Carmen (LT)', year: 2021, water: 'Lagos Los Búhos', impact: 'Desarrollo' }, { name: 'No. 29 Mudela del Río (LT)', year: 2024, water: 'Canal Guaymaral; quebradas Novita y Torca', impact: 'Desarrollo' }],
}
const el = ref<HTMLDivElement>(); let chart: echarts.ECharts | undefined; let observer: ResizeObserver | undefined
function render() { if (!el.value || chart || !el.value.clientWidth) return; fetch('/data/maps/bogota-localidades.geojson').then(r => r.json()).then(geojson => { if (!el.value || chart) return; const points = geojson.features.flatMap((f: { geometry: { coordinates: number[][][] } }) => f.geometry.coordinates.flat(1)); const xs = points.map(p => p[0]); const ys = points.map(p => p[1]); const cx = (Math.min(...xs) + Math.max(...xs)) / 2; const cy = (Math.min(...ys) + Math.max(...ys)) / 2; const rotate = (value: unknown): unknown => Array.isArray(value) && typeof value[0] === 'number' ? [cx - ((value[1] as number) - cy), cy + ((value[0] as number) - cx)] : (value as unknown[]).map(rotate); geojson.features.forEach((f: { properties: Record<string, string>; geometry: { coordinates: unknown } }) => { f.properties.name = f.properties.LocNombre; f.geometry.coordinates = rotate(f.geometry.coordinates) }); echarts.registerMap('bogota-localidades', geojson); chart = echarts.init(el.value); chart.setOption({ animationDuration: 650, tooltip: { trigger: 'item', confine: true, backgroundColor: '#0c1417', borderColor: '#526665', textStyle: { color: '#f3f0e7', fontSize: 10 }, extraCssText: 'max-width:270px;white-space:normal;line-height:1.3;padding:9px', formatter: (p: { name: string }) => { const entries = plans[p.name] || []; if (!entries.length) return `<b>${p.name}</b><br/><span style="color:#afbfba">Sin plan parcial incluido en la tabla oficial 2015–2025.</span>`; return `<b>${p.name}</b><br/><span style="color:#dfbb72">${entries.length} registro${entries.length > 1 ? 's' : ''} en la tabla</span><br/><br/>${entries.map(x => `<b>${x.name}</b> · ${x.year}<br/>${x.water}<br/><span style="color:#afbfba">${x.impact}</span>`).join('<br/><br/>')}<br/><br/><span style="color:#86c8c0">Fuente: SDP, memorando 3-2025-14164-1 · 02 may. 2025.</span>` } }, visualMap: { show: true, type: 'piecewise', orient: 'horizontal', left: 'center', bottom: 7, textStyle: { color: '#afbfba', fontSize: 8 }, itemWidth: 14, itemHeight: 8, itemGap: 6, pieces: [{ value: 1, label: '1', color: '#86c8c0' }, { value: 2, label: '2', color: '#b2ca91' }, { value: 3, label: '3', color: '#dfbb72' }, { value: 4, label: '4', color: '#d88b5c' }, { value: 5, label: '5 planes', color: '#c9634d' }] }, series: [{ type: 'map', map: 'bogota-localidades', nameProperty: 'name', roam: false, zoom: 1.08, label: { show: true, fontSize: 7, color: '#e5eee9', formatter: (p: { name: string }) => plans[p.name] ? `${p.name}\n${plans[p.name].length}` : '' }, emphasis: { label: { show: true, color: '#f3f0e7', fontSize: 9 }, itemStyle: { areaColor: '#b8dfd9' } }, itemStyle: { areaColor: '#1a292d', borderColor: '#405357', borderWidth: .55 }, data: Object.entries(plans).map(([name, records]) => ({ name, value: records.length })) }] }) }) }
onMounted(() => { if (!el.value) return; observer = new ResizeObserver(() => { render(); chart?.resize() }); observer.observe(el.value); requestAnimationFrame(render); const navigation = window.setInterval(() => { if (!chart) return; chart.setOption({ series: [{ roam: true, scaleLimit: { min: 0.8, max: 8 } }] }); window.clearInterval(navigation) }, 50) }); onBeforeUnmount(() => { observer?.disconnect(); chart?.dispose() })
</script>
<template><section class="partial-map"><div class="partial-map__title">21 planes parciales adoptados · 2015–2025 · norte ←</div><div ref="el" class="partial-map__canvas" role="img" aria-label="Mapa horizontal de localidades de Bogotá coloreado por número de los veintiún planes parciales que incluyen rondas hídricas."/></section></template>
